-- Materi BRP-18 (Blok 18 Sistem Reproduksi): 31 bab PDF dalam 6 kelompok.
-- Disiapkan menggunakan pola impor BRS-13; berkas PDF & gambar halaman sudah ada di storage server.
-- Aman dijalankan pada database kosong (semua INSERT bergantung pada Blok BRP-18 yang ada).

-- Topik lama yang masih terbit (contoh 'Bab 1') disembunyikan, riwayatnya tetap.
UPDATE Topic SET published = false WHERE categoryId = (SELECT id FROM Category WHERE code = 'BRP-18') AND published = true AND id NOT LIKE 'dea-brp18-%';
-- Deskripsi kelas bawaan menyebut kuis per Bab; diganti hanya bila belum diubah admin.
UPDATE Category SET description = 'Blok 18 tahap akademik (preklinik). 31 bab sistem reproduksi dalam 6 bagian, dari struktur dan fisiologi hingga kelainan dan kesehatan reproduksi. Bagian 1 (bab 1–5) gratis untuk akun terdaftar.' WHERE code = 'BRP-18' AND description LIKE 'Blok 18 tahap akademik (preklinik). Materi dibagi per Bab%';

INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-brp18-group-1', id, 'Dasar Anatomi dan Perkembangan', 'Bab 1–5. Gratis untuk semua akun terdaftar.', 1, true FROM Category WHERE code = 'BRP-18';
INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-brp18-group-2', id, 'Fisiologi dan Fertilisasi', 'Bab 6–10. Tersedia untuk pemilik paket Blok Reproduksi atau Basic Medical Science.', 2, true FROM Category WHERE code = 'BRP-18';
INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-brp18-group-3', id, 'Kehamilan, Laktasi dan Penuaan', 'Bab 11–15. Tersedia untuk pemilik paket Blok Reproduksi atau Basic Medical Science.', 3, true FROM Category WHERE code = 'BRP-18';
INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-brp18-group-4', id, 'Kelainan Ginekologi', 'Bab 16–20. Tersedia untuk pemilik paket Blok Reproduksi atau Basic Medical Science.', 4, true FROM Category WHERE code = 'BRP-18';
INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-brp18-group-5', id, 'Kelainan Serviks, Ovarium, Panggul dan Reproduksi Pria', 'Bab 21–25. Tersedia untuk pemilik paket Blok Reproduksi atau Basic Medical Science.', 5, true FROM Category WHERE code = 'BRP-18';
